test("leaves a value inside the range alone", () => {
  assert.equal(clamp(5, 0, 10), 5);
});

test("returns low when value is below the range", () => {
  assert.equal(clamp(-3, 0, 10), 0);
});

test("returns high when value is above the range", () => {
  assert.equal(clamp(15, 0, 10), 10);
});

test("handles boundary values equal to low", () => {
  assert.equal(clamp(0, 0, 10), 0);
});

test("handles boundary values equal to high", () => {
  assert.equal(clamp(10, 0, 10), 10);
});
